create table if not exists public.collective_portal_identities(id uuid primary key default gen_random_uuid(),roster_student_id uuid not null references public.roster_students(id) on delete restrict,owner_user_id uuid not null,school_id uuid references public.schools(id) on delete set null,status text not null default 'ACTIVE' check(status in ('ACTIVE','SUSPENDED','ARCHIVED')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_user_id,roster_student_id));
create table if not exists public.collective_portal_credentials(id uuid primary key default gen_random_uuid(),portal_identity_id uuid not null references public.collective_portal_identities(id) on delete cascade,password_hash text not null,password_lookup_key text not null,password_version integer not null default 1,failed_attempts integer not null default 0,locked_until timestamptz,last_login_at timestamptz,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(portal_identity_id),unique(password_lookup_key));
create table if not exists public.collective_portal_sessions(id uuid primary key default gen_random_uuid(),portal_identity_id uuid not null references public.collective_portal_identities(id) on delete cascade,credential_version integer not null,token_hash text not null unique,expires_at timestamptz not null,last_seen_at timestamptz not null default now(),revoked_at timestamptz,created_at timestamptz not null default now());
alter table public.collective_access_sessions add column if not exists session_type text not null default 'COMPETITION';
alter table public.collective_access_sessions add column if not exists competition_id uuid references public.competitions(id) on delete cascade;
alter table public.collective_access_sessions add column if not exists portal_session_id uuid references public.collective_portal_sessions(id) on delete set null;
create index if not exists idx_collective_portal_credentials_lookup on public.collective_portal_credentials(password_lookup_key) where enabled=true;
create index if not exists idx_collective_portal_sessions_token on public.collective_portal_sessions(token_hash) where revoked_at is null;
create index if not exists idx_collective_access_sessions_competition on public.collective_access_sessions(competition_id,collective_participant_id) where revoked_at is null;
create index if not exists idx_collective_participants_roster_status on public.collective_participants(roster_student_id,status,competition_id);
create or replace function private.collective_portal_identity(p_token text) returns uuid language sql security definer set search_path=public,private as $$select portal_identity_id from public.collective_portal_sessions where token_hash=private.hash_collective_token(trim(coalesce(p_token,''))) and revoked_at is null and expires_at>now() order by created_at desc limit 1$$;
create or replace function private.sync_collective_portal_credential(p_participant_id uuid,p_plaintext_password text,p_password_version integer) returns uuid language plpgsql security definer set search_path=public,private,extensions as $$declare cp public.collective_participants%rowtype;pi uuid;begin select * into cp from public.collective_participants where id=p_participant_id;if cp.id is null then raise exception 'COLLECTIVE_PARTICIPANT_NOT_FOUND';end if;select id into pi from public.collective_portal_identities where owner_user_id=cp.managed_by_user_id and roster_student_id=cp.roster_student_id;if pi is null then insert into public.collective_portal_identities(roster_student_id,owner_user_id,school_id) values(cp.roster_student_id,cp.managed_by_user_id,cp.school_id) returning id into pi;end if;if trim(coalesce(p_plaintext_password,''))<>'' then insert into public.collective_portal_credentials(portal_identity_id,password_hash,password_lookup_key,password_version) values(pi,crypt(p_plaintext_password,gen_salt('bf',12)),encode(digest(left(trim(p_plaintext_password),8),'sha256'),'hex'),greatest(1,p_password_version)) on conflict(portal_identity_id) do nothing;end if;return pi;end$$;
create or replace function public.verify_collective_portal_password(p_password text) returns jsonb language plpgsql security definer set search_path=public,private,extensions as $$declare c public.collective_portal_credentials%rowtype;pi public.collective_portal_identities%rowtype;t text;lk text;begin lk:=encode(digest(left(trim(coalesce(p_password,'')),8),'sha256'),'hex');select * into c from public.collective_portal_credentials where enabled and password_lookup_key=lk limit 1;if c.id is null then return jsonb_build_object('ok',false,'reason','INVALID_CREDENTIALS');end if;if c.locked_until is not null and c.locked_until>now() then return jsonb_build_object('ok',false,'reason','LOCKED');end if;if crypt(coalesce(p_password,''),c.password_hash) is distinct from c.password_hash then update public.collective_portal_credentials set failed_attempts=failed_attempts+1,locked_until=case when failed_attempts+1>=5 then now()+interval '15 minutes' else locked_until end,updated_at=now() where id=c.id;return jsonb_build_object('ok',false,'reason','INVALID_CREDENTIALS');end if;select * into pi from public.collective_portal_identities where id=c.portal_identity_id and status='ACTIVE';if pi.id is null then return jsonb_build_object('ok',false,'reason','ACCESS_NOT_READY');end if;update public.collective_portal_credentials set failed_attempts=0,locked_until=null,last_login_at=now(),updated_at=now() where id=c.id;t:=encode(gen_random_bytes(32),'hex');insert into public.collective_portal_sessions(portal_identity_id,credential_version,token_hash,expires_at) values(pi.id,c.password_version,private.hash_collective_token(t),now()+interval '8 hours');return jsonb_build_object('ok',true,'portal_token',t,'portal_identity_id',pi.id);end$$;
create or replace function public.list_collective_portal_competitions(p_portal_token text) returns table(participant_id uuid,competition_id uuid,competition_title text,competition_status text,starts_at timestamptz,ends_at timestamptz,participant_code text,participant_status text) language sql security definer set search_path=public,private as $$select cp.id,c.id,c.title,c.status,c.starts_at,c.ends_at,cp.participant_code,cp.status from public.collective_portal_sessions ps join public.collective_portal_identities pi on pi.id=ps.portal_identity_id join public.collective_participants cp on cp.roster_student_id=pi.roster_student_id and cp.managed_by_user_id=pi.owner_user_id join public.competitions c on c.id=cp.competition_id join public.collective_portal_credentials pc on pc.portal_identity_id=pi.id and pc.enabled and pc.password_version=ps.credential_version where ps.token_hash=private.hash_collective_token(trim(coalesce(p_portal_token,''))) and ps.revoked_at is null and ps.expires_at>now() and pi.status='ACTIVE' and cp.status='ACTIVE' order by coalesce(c.starts_at,c.created_at),c.id$$;
create or replace function public.open_collective_competition_session(p_portal_token text,p_participant_code text) returns jsonb language plpgsql security definer set search_path=public,private,extensions as $$declare pi uuid:=private.collective_portal_identity(p_portal_token);cp public.collective_participants%rowtype;ps public.collective_portal_sessions%rowtype;t text;begin if pi is null then return jsonb_build_object('ok',false,'reason','PORTAL_SESSION_INVALID');end if;select * into ps from public.collective_portal_sessions where portal_identity_id=pi and token_hash=private.hash_collective_token(trim(coalesce(p_portal_token,''))) and revoked_at is null and expires_at>now() limit 1;if ps.id is null then return jsonb_build_object('ok',false,'reason','PORTAL_SESSION_INVALID');end if;if not exists(select 1 from public.collective_portal_credentials where portal_identity_id=pi and enabled and password_version=ps.credential_version) then return jsonb_build_object('ok',false,'reason','CREDENTIAL_REVOKED');end if;select * into cp from public.collective_participants where roster_student_id=(select roster_student_id from public.collective_portal_identities where id=pi) and managed_by_user_id=(select owner_user_id from public.collective_portal_identities where id=pi) and upper(participant_code)=upper(trim(p_participant_code)) and status='ACTIVE' limit 1;if cp.id is null then return jsonb_build_object('ok',false,'reason','INVALID_PARTICIPANT_CODE');end if;t:=encode(gen_random_bytes(32),'hex');insert into public.collective_access_sessions(collective_participant_id,competition_id,session_type,portal_session_id,token_hash,expires_at) values(cp.id,cp.competition_id,'COMPETITION',ps.id,private.hash_collective_token(t),now()+interval '8 hours');update public.collective_portal_sessions set last_seen_at=now() where id=ps.id;return jsonb_build_object('ok',true,'access_token',t,'participant_id',cp.id,'competition_id',cp.competition_id,'participant_code',cp.participant_code,'full_name',cp.full_name,'class_name',cp.class_name,'grade',cp.grade,'school_id',cp.school_id,'photo_url',cp.photo_url,'user_id',cp.user_id);end$$;
create or replace function public.revoke_collective_portal_session(p_portal_token text) returns boolean language sql security definer set search_path=public,private as $$update public.collective_portal_sessions set revoked_at=coalesce(revoked_at,now()),last_seen_at=now() where token_hash=private.hash_collective_token(trim(coalesce(p_portal_token,''))) and revoked_at is null returning true$$;
revoke all on function public.verify_collective_portal_password(text) from public;grant execute on function public.verify_collective_portal_password(text) to anon,authenticated,service_role;
revoke all on function public.list_collective_portal_competitions(text) from public;grant execute on function public.list_collective_portal_competitions(text) to anon,authenticated,service_role;
revoke all on function public.open_collective_competition_session(text,text) from public;grant execute on function public.open_collective_competition_session(text,text) to anon,authenticated,service_role;
revoke all on function public.revoke_collective_portal_session(text) from public;grant execute on function public.revoke_collective_portal_session(text) to anon,authenticated,service_role;